const $=id=>document.getElementById(id), editor=$('editor'),storyDialog=$('storyDialog');let current=0,lang='en',state={name:'',birth:'',answers:{},photos:{},biography:'',message:''};try{state={...state,...JSON.parse(localStorage.getItem('miniography-v1')||'{}')}}catch{};
const themes=['Your beginnings','A place called home','Childhood treasures','The people around you','Little traditions','Growing into yourself','Friendship','Learning along the way','A first adventure','Finding your own way','Meaningful connections','Turning points','The work of your hands','Places that stay with you','Everyday joy','Your kind of person','A proud moment','Through difficult times','What matters most','A perfect little day','A letter to your younger self','Dreams still unfolding','For those who come after','Your story, revealed'];
const deThemes=['Deine Anfänge','Ein Ort namens Zuhause','Kindheitsschätze','Die Menschen um dich','Kleine Traditionen','Du selbst werden','Freundschaft','Was du gelernt hast','Ein erstes Abenteuer','Dein eigener Weg','Wichtige Verbindungen','Wendepunkte','Was du erschaffst','Unvergessliche Orte','Freude im Alltag','Deine Persönlichkeit','Ein stolzer Moment','Schwierige Zeiten','Was wirklich zählt','Ein schöner Tag','An dein jüngeres Ich','Träume für morgen','Für die Zukunft','Deine Geschichte'];
const questions=['Where does your story begin? Tell us about when and where you were born.','What place felt like home when you were growing up?','What small childhood memory still makes you smile?','Who made you feel seen and cared for as you grew up?','What tradition, meal, or celebration holds a special place in your memory?','When did you start to feel like your own person?','Tell us about a friendship that means a lot to you.','What did you learn, in or out of a classroom, that has stayed with you?','What adventure took you beyond the familiar?','What interest or passion have you chosen to follow?','Who has made a meaningful difference in your life?','What experience or decision has influenced who you are today?','What have you enjoyed making, doing, studying, or contributing?','Which place would you like to return to, and why?','What brings you joy in an ordinary week?','What little quirks or qualities make you you?','What is something you feel proud of?','What has helped you through a difficult time?','What values guide the choices you make?','Describe a day you would love to live again.','What would you like to tell your younger self?','What are you curious about or looking forward to?','What message would you like to leave for future generations?'];
const deQuestions=['Wo beginnt deine Geschichte? Wann und wo wurdest du geboren?','Welcher Ort war in deiner Kindheit dein Zuhause?','Welche kleine Kindheitserinnerung bringt dich zum Lächeln?','Wer hat dir als Kind Geborgenheit gegeben?','Welche Tradition, Mahlzeit oder Feier bedeutet dir viel?','Wann hast du begonnen, deinen eigenen Weg zu gehen?','Erzähle von einer Freundschaft, die dir viel bedeutet.','Was hast du gelernt, das dich bis heute begleitet?','Welches Abenteuer führte dich ins Unbekannte?','Welchem Interesse oder welcher Leidenschaft gehst du nach?','Wer hat dein Leben bereichert?','Welche Erfahrung oder Entscheidung hat dich geprägt?','Was erschaffst, lernst oder tust du besonders gerne?','An welchen Ort würdest du gerne zurückkehren?','Was bereitet dir im Alltag Freude?','Welche Eigenheiten machen dich aus?','Worauf bist du stolz?','Was hat dir in einer schwierigen Zeit geholfen?','Welche Werte leiten dich?','Welchen Tag würdest du gerne noch einmal erleben?','Was möchtest du deinem jüngeren Ich sagen?','Worauf freust du dich in der Zukunft?','Welche Botschaft möchtest du zukünftigen Generationen mitgeben?'];
const symbols=['✳','⌂','✧','❋','❧','❀','∞','✎','✦','➶','♡','✧','❋','⌁','☼','✳','✦','❧','◇','☼','✎','✧','❦','✴'];
function toast(t){$('toast').textContent=t;$('toast').style.display='block';setTimeout(()=>$('toast').style.display='none',4000)}
function save(){try{localStorage.setItem('miniography-v1',JSON.stringify(state));$('saved').textContent=lang==='de'?'Auf diesem Gerät gespeichert':'Saved on this device';render()}catch{$('saved').textContent='Storage full — export a backup';toast('Could not save. Please export a backup.')}}
function unlocked(i){const d=new Date();return $('preview').checked||(d.getMonth()===11&&d.getDate()>=i+1)}
function render(){const n=Object.values(state.answers).filter(a=>a.trim()).length;$('count').textContent=lang==='de'?`${n} von 23 Erinnerungen gesammelt`:`${n} of 23 memories collected`;$('bar').style.width=n/23*100+'%';$('grid').replaceChildren();themes.forEach((t,i)=>{const b=document.createElement('button');b.className='door'+(state.answers[i]?.trim()?' done':'')+(i===23?' reveal':'');b.innerHTML=`<span class="lock">${state.answers[i]?.trim()?'✦':unlocked(i)?'':'⌑'}</span><span class="symbol">${symbols[i]}</span><span class="num">${String(i+1).padStart(2,'0')}</span><small></small>`;b.querySelector('small').textContent=(lang==='de'?deThemes:themes)[i];b.setAttribute('aria-label',`${i+1}: ${(lang==='de'?deThemes:themes)[i]}`);b.onclick=()=>openDoor(i);$('grid').append(b)})}
function question(i){let q=(lang==='de'?deQuestions:questions)[i];let age=new Date().getFullYear()-Number(state.birth);if(i===11){q=lang==='de'?(age<30?'Welche Erfahrung oder Entscheidung hat dein heutiges Ich geprägt?':age<50?'Welche Entscheidung hat deinem Leben eine neue Richtung gegeben?':age<70?'Welche Momente haben dein Leben besonders geprägt?':'Welche Ereignisse haben im Lauf der Jahre deinen Lebensweg verändert?'):(age<30?questions[11]:age<50?'Which decision or unexpected event has most changed the direction of your life?':age<70?'Looking back, which moments or decisions have most shaped your life?':'When you think back over the years, which events changed the course of your life?')}else if(i>0&&state.birth){q+=(lang==='de'?(age<30?' Denke an deine bisherigen Erfahrungen.':age<50?' Was bedeutet dir das heute?':age<70?' Wie hat sich dein Blick darauf verändert?':' Welche Einzelheiten sind dir besonders in Erinnerung geblieben?'):(age<30?' Think about your experiences so far.':age<50?' What does that mean to you today?':age<70?' How has your perspective on this changed?':' Which details have stayed with you over the years?'))}return q}
function openDoor(i){if(!unlocked(i)){toast(lang==='de'?`Dieses Türchen öffnet am ${i+1}. Dezember. Nutze die Vorschau zum Erkunden.`:`This door opens December ${i+1}. Turn on preview to explore.`);return}if(i>0&&(!state.birth||!validAge())){toast(lang==='de'?'Bitte beginne mit Tür 1 und deinem Geburtsjahr.':'Start with door 1 and enter your birth year.');i=0}if(i===23){story();return}current=i;$('dayLabel').textContent=`${lang==='de'?'TÜR':'DOOR'} ${String(i+1).padStart(2,'0')} · ${lang==='de'?'DEINE ERINNERUNGEN':'YOUR MEMORIES'}`;$('title').textContent=(lang==='de'?deThemes:themes)[i];$('profile').style.display=i===0?'grid':'none';$('name').value=state.name;$('birth').value=state.birth;$('birth').max=new Date().getFullYear()-18;$('question').textContent=question(i);$('answer').value=state.answers[i]||'';$('answer').placeholder=lang==='de'?'Fang einfach an. Jedes kleine Detail zählt.':'Start anywhere. A little detail can hold a whole memory…';$('followup').textContent=lang==='de'?'Wer war dabei? Was konntest du sehen, hören oder fühlen? Erzähle so viel oder so wenig du möchtest.':'Who was there? What could you see, hear, or feel? Add as much or as little as you like.';renderPhotos();if(!editor.open)editor.showModal()}
function validAge(){return Number.isInteger(+state.birth)&&+state.birth>=1900&&+state.birth<=new Date().getFullYear()-18}
$('answer').oninput=()=>{state.answers[current]=$('answer').value;save()};$('name').oninput=()=>{state.name=$('name').value;save()};$('birth').oninput=()=>{state.birth=$('birth').value;save()};function nextDoor(){if(!validAge()){toast('Please enter a valid birth year (18+ by birth year).');return}save();if(current===22){editor.close();story()}else{editor.close();openDoor(current+1)}}
$('photo').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>3e6){toast('Please choose a JPG, PNG or WebP under 3 MB.');return}if(Object.values(state.photos).flat().length>=3){toast('You can include up to 3 photographs.');return}const reader=new FileReader();reader.onload=()=>{(state.photos[current]??=[]).push(reader.result);save();renderPhotos()};reader.readAsDataURL(f);e.target.value=''};
function renderPhotos(){$('photos').replaceChildren();(state.photos[current]||[]).forEach((src,i)=>{const b=document.createElement('button');b.title='Remove photograph';const img=new Image();img.src=src;img.alt='Your memory photograph';b.append(img);b.onclick=()=>{state.photos[current].splice(i,1);save();renderPhotos()};$('photos').append(b)})}
function buildStory(force=false){if(!state.biography||force)state.biography=Object.keys(state.answers).sort((a,b)=>a-b).filter(k=>state.answers[k].trim()).map(k=>(lang==='de'?deThemes:themes)[k]+'\n\n'+state.answers[k]).join('\n\n');$('biography').value=state.biography;save()}
function story(){buildStory();$('message').value=state.message||state.answers[22]||'';storyDialog.showModal()}
$('biography').oninput=()=>{state.biography=$('biography').value;save()};$('message').oninput=()=>{state.message=$('message').value;save()};
function printStory(){let old=$('printSheet');if(old)old.remove();const sheet=document.createElement('article');sheet.id='printSheet';sheet.style.display='none';const h=document.createElement('h1');h.textContent=state.name?state.name+' — Miniography':'My Miniography';sheet.append(h);Object.values(state.photos).flat().forEach(src=>{const img=new Image();img.src=src;sheet.append(img)});const p=document.createElement('div');p.style.whiteSpace='pre-wrap';p.textContent=state.biography||'Your story is still unfolding.';sheet.append(p);if(state.message){const q=document.createElement('blockquote');q.textContent=state.message;sheet.append(q)}document.body.append(sheet);setTimeout(()=>window.print(),100)}
function toggleLang(){lang=lang==='en'?'de':'en';document.documentElement.lang=lang;$('language').textContent=lang==='de'?'DE / EN':'EN / DE';$('season').textContent=lang==='de'?'DEIN ADVENT · 1.–24. DEZEMBER':'THE ADVENT OF YOU · DECEMBER 1–24';document.querySelector('h1').innerHTML=lang==='de'?'Dein Leben.<br>Eine kleine <em>Geschichte</em><br>nach der anderen.':'Your life.<br>One little <em>story</em><br>at a time.';$('intro').textContent=lang==='de'?'24 Türchen. Ein paar ruhige Momente. Ein Leben voller Erinnerungen.':'24 doors. A few quiet moments. A lifetime of you.';$('begin').textContent=lang==='de'?'Öffne dein erstes Türchen ↗':'Open your first door ↗';$('calendarTitle').textContent=lang==='de'?'Dein Dezember voller Erinnerungen':'Your December of memories';render()}
render();
async function exportArchive(){try{const zip=new JSZip();const data=structuredClone(state);const media=[];for(const [day,photos]of Object.entries(data.photos)){data.photos[day]=photos.map((src,i)=>{const type=src.slice(5,src.indexOf(';'));const file=`media/day-${+day+1}-${i+1}.${type==='image/jpeg'?'jpg':type.split('/')[1]}`;zip.file(file,src.split(',')[1],{base64:true});media.push(file);return file})}zip.file('miniography.json',JSON.stringify({format:'miniography',version:1,exportedAt:new Date().toISOString(),language:lang,participant:{name:state.name,birthYear:state.birth},...data},null,2));zip.file('README.txt','Miniography v1\nOpen ZIP archive. miniography.json contains original answers, participant information, editable story and photo paths. Media contains original uploaded photographs.');const blob=await zip.generateAsync({type:'blob'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='my-story.miniography';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Archive exported. Keep it somewhere safe.')}catch{toast('Export failed. Please try again.')}}
$('importFile').onchange=async e=>{try{const f=e.target.files[0];if(!f)return;if(f.size>15e6)throw Error();const zip=await JSZip.loadAsync(f);const entry=zip.file('miniography.json');if(!entry)throw Error();const data=JSON.parse(await entry.async('string'));if(data.format!=='miniography'||data.version!==1||typeof data.answers!=='object'||!data.answers||Array.isArray(data.answers))throw Error();const incoming={name:String(data.name||'').slice(0,100),birth:String(data.birth||''),answers:{},photos:{},biography:String(data.biography||''),message:String(data.message||'')};for(const [key,value]of Object.entries(data.answers)){if(!/^([0-9]|1[0-9]|2[0-2])$/.test(key)||typeof value!=='string')throw Error();incoming.answers[key]=value}let total=0;for(const [day,paths]of Object.entries(data.photos||{})){if(!/^([0-9]|1[0-9]|2[0-2])$/.test(day)||!Array.isArray(paths))throw Error();incoming.photos[day]=[];for(const path of paths){if(++total>3||typeof path!=='string'||!/^media\/[a-zA-Z0-9_-]+\.(png|jpg|jpeg|webp)$/.test(path))throw Error();const file=zip.file(path);if(!file)throw Error();const buffer=await file.async('uint8array');if(buffer.length>3e6)throw Error();const ext=path.split('.').pop();incoming.photos[day].push(`data:image/${ext==='jpg'?'jpeg':ext};base64,`+await file.async('base64'))}}if(Object.values(state.answers).some(Boolean)&&!confirm('Replace your current memories with this archive? Export a backup first if needed.'))return;state=incoming;save();toast('Your memories have been imported.')}catch{toast('This archive could not be imported. Please use a valid .miniography file.')}e.target.value=''};
